/* Workspace organization and reversible panel preferences. */
(()=>{
 const pages={home:['Choose how you want to learn.','Explore a live lab, work through a guided problem, or prepare for the exam.'],lesson:['Build a resultant force.','Explore force directions, signed components and vector addition.'],position:['Turn geometry into a force.','Locate points, find displacement and normalize the cable direction.'],projection:['Find the force along an axis.','Connect axis geometry, unit vectors and signed force projections.'],moment:['See how a force creates rotation.','Explore moment arms, cross products and the right-hand rule.'],axisWorkspace:['Find the moment about an axis.','Normalize the axis, calculate the point moment and project the signed twist.'],coupleWorkspace:['Understand a force couple.','Investigate equal and opposite forces, line spacing and reference-independent moments.'],quiz:['Check your fundamental concepts.','Practice multiple-choice and true/false questions, with explanations after checking.'],exam:['Practice the 120-minute exam.','Complete 7 multiple-choice, 6 true/false and 4 calculation problems.'],roadmap:['Solve one decision at a time.','Work through a problem, answer each step and understand why the method works.'],assessment:['Check concepts. Practice the exam.','Review fundamentals or attempt the updated 120-minute mock exam.'],practice:['Practice resultant forces.','Apply the component method before revealing a worked solution.'],reference:['Choose the equation that fits.','Check required information, variable meanings, conditions and units.']};
 const labs=['lesson','position','projection','moment','axisWorkspace','coupleWorkspace','systemsWorkspace','locationWorkspace','distributedWorkspace','integralsWorkspace'];let collapsed={};try{collapsed=JSON.parse(localStorage.getItem('statics-panels-v1')||'{}')||{};}catch{}if(typeof collapsed!=='object'||Array.isArray(collapsed))collapsed={};const save=()=>{try{localStorage.setItem('statics-panels-v1',JSON.stringify(collapsed));}catch{}};
 function fold(node,key,title,description,heading){if(node.dataset.folded)return;node.dataset.folded='true';const details=document.createElement('details');details.className='workspace-fold';const legacyKey=key.replace(/^axisWorkspace:/,'axisCouple:').replace(/^coupleWorkspace:panel:(\d+)$/,(_,i)=>'axisCouple:panel:'+(Number(i)+4)).replace(/^coupleWorkspace:/,'axisCouple:');details.open=!(collapsed[key]??collapsed[legacyKey]);const summary=document.createElement('summary'),name=document.createElement('strong'),desc=document.createElement('span');name.textContent=title.replace(/^(\d{2})(?=\S)/,'$1 · ');desc.textContent=description;summary.append(name,desc);const body=document.createElement('div');body.className='workspace-body';while(node.firstChild)body.appendChild(node.firstChild);if(heading)heading.remove();details.append(summary,body);node.appendChild(details);details.addEventListener('toggle',()=>{collapsed[key]=!details.open;save();if(details.open)body.querySelectorAll('svg').forEach(svg=>GraphScales.layout(svg));});}
 function enhance(){for(const id of labs){const view=$(id);view?.querySelectorAll('article.panel').forEach((panel,i)=>{const heading=panel.querySelector('.panel-heading')||panel.querySelector('h3,h2'),title=heading?.querySelector('h3,h2')?.textContent||heading?.textContent||'Practice and concepts';const desc=panel.querySelector('svg')?'Adjust the inputs and explore the live geometry.':panel.querySelector('.step')?'Follow equations, variable meanings and calculation steps.':panel.classList.contains('position-practice')?'Check your answers with guided practice.':'Review the concepts and their conditions.';fold(panel,id+':panel:'+i,title,desc,heading);});view?.querySelectorAll('.step').forEach(step=>{const heading=step.querySelector('.step-title');fold(step,id+':step:'+step.dataset.equation,heading?.textContent||'Calculation step','Open the equation and its explanation.',heading);});}}
 function activate(name){const custom={systemsWorkspace:['Reduce a force and couple system.','Preserve total force and total moment.'],locationWorkspace:['Locate the equivalent resultant.','Match the original moment to determine the line of action.'],distributedWorkspace:['Replace distributed loads.','Connect load intensity, area, centroid and equivalent force.'],integralsWorkspace:['Understand integration in statics.','Accumulate force and first moment from a load function.'],mastery:['See your demonstrated progress.','Separate supported study from independent performance.']};const page=pages[name]||custom[name]||pages.home;$('pageTitle').textContent=page[0];$('pageDescription').textContent=page[1];$('pageCategory').textContent=labs.includes(name)?'WORKSPACE / EXPLORE & LEARN':name==='roadmap'?'SOLID MECHANICS ROADMAP / GUIDED PROBLEMS':'STUDY LAB / '+name.toUpperCase();document.title=page[0]+' | Statics Study Lab';$('workspaceTools').hidden=!labs.includes(name);enhance();}
 window.StudyExperience={activate};$('collapseWorkspace').onclick=()=>document.querySelectorAll('.view:not([hidden]) .workspace-fold').forEach(d=>d.open=false);$('expandWorkspace').onclick=()=>document.querySelectorAll('.view:not([hidden]) .workspace-fold').forEach(d=>d.open=true);
 $('axisWorkspace').appendChild($('axisLesson'));$('axisLesson').hidden=false;$('coupleWorkspace').appendChild($('coupleLesson'));$('coupleLesson').hidden=false;
 let folders={};try{folders=JSON.parse(localStorage.getItem('statics-navigation-v1')||'{}')||{};}catch{}document.querySelectorAll('nav details').forEach(folder=>{if(typeof folders[folder.id]==='boolean')folder.open=folders[folder.id];folder.addEventListener('toggle',()=>{folders[folder.id]=folder.open;try{localStorage.setItem('statics-navigation-v1',JSON.stringify(folders));}catch{}});});
 document.querySelectorAll('[data-open-view]').forEach(b=>b.onclick=()=>showView(b.dataset.openView));document.querySelectorAll('nav [data-roadmap-topic]').forEach(b=>b.onclick=()=>GuidedRoadmap.open(b.dataset.roadmapTopic));
 let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;enhance();});}).observe(document.querySelector('main'),{childList:true,subtree:true});enhance();if(!window.examInProgress)showView('lesson');else activate('exam');
})();
